(async () => {
  "use strict";
  const storage = MogledgeStorage.create({ appId: "generated-calculator", schemaVersion: 1 });
  const amount = document.querySelector("#amount");
  const mode = document.querySelector("#mode");
  const enabled = document.querySelector("#enabled");
  const result = document.querySelector("#result");
  const status = document.querySelector("#status");
  const saveButton = document.querySelector("#save");
  const reloadButton = document.querySelector("#reload");
  const controls = [amount, mode, enabled];
  let initialized = false;
  let timer;
  let generation = 0;

  function state() {
    return { amount: Number(amount.value), mode: mode.value, enabled: enabled.checked };
  }
  function valid(value) {
    return value && typeof value.amount === "number" && Number.isFinite(value.amount)
      && ["double", "square"].includes(value.mode) && typeof value.enabled === "boolean";
  }
  function restore(value) {
    if (!valid(value)) throw new Error("保存値の形式が異なります。保存値は変更していません。");
    amount.value = String(value.amount);
    mode.value = value.mode;
    enabled.checked = value.enabled;
  }
  function calculate() {
    const value = state();
    result.value = !value.enabled ? "無効" : String(value.mode === "double" ? value.amount * 2 : value.amount ** 2);
  }
  function failed(error) {
    status.textContent = "保存できません: " + (error.code || error.message);
  }
  async function saveNow() {
    clearTimeout(timer);
    if (!initialized) throw new Error("復元に失敗したため保存を停止しています");
    const currentGeneration = generation;
    status.textContent = "保存中…";
    await storage.write(state());
    await storage.flush();
    if (generation === currentGeneration) status.textContent = "保存済み";
  }

  for (const control of controls) control.disabled = true;
  saveButton.disabled = reloadButton.disabled = true;
  try {
    const saved = await storage.read();
    if (saved !== null) restore(saved);
    initialized = true;
    status.textContent = saved === null ? "保存値なし" : "復元済み";
  } catch (error) {
    failed(error);
  } finally {
    for (const control of controls) control.disabled = false;
    saveButton.disabled = reloadButton.disabled = !initialized;
    calculate();
  }

  for (const control of controls) control.addEventListener("input", () => {
    generation++;
    calculate();
    if (!initialized) return;
    status.textContent = "未保存";
    clearTimeout(timer);
    timer = setTimeout(() => { saveNow().catch(failed); }, 100);
  });
  saveButton.addEventListener("click", () => { saveNow().catch(failed); });
  reloadButton.addEventListener("click", async () => {
    for (const control of controls) control.disabled = true;
    saveButton.disabled = reloadButton.disabled = true;
    try {
      await saveNow();
      location.reload();
    } catch (error) {
      failed(error);
      for (const control of controls) control.disabled = false;
      saveButton.disabled = reloadButton.disabled = !initialized;
    }
  });

})();
